-- Run once in Supabase SQL Editor. No public admin registration is permitted.
create extension if not exists pgcrypto;
create table public.admin_profiles(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name_en text not null unique,name_hi text not null default '',sort_order integer not null default 0);
create table public.products(id uuid primary key default gen_random_uuid(),slug text not null unique,name_en text not null,name_hi text not null default '',description_en text not null default '',description_hi text not null default '',category_id uuid references public.categories(id) on delete set null,price_per_kg numeric(12,2) not null default 0 check(price_per_kg>=0),active boolean not null default true,featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,grams integer not null check(grams>0),price numeric(12,2) not null check(price>=0),active boolean not null default true,sort_order integer not null default 0,unique(product_id,grams));
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,url text not null,storage_path text,sort_order integer not null default 0);
create table public.promotions(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,variant_id uuid references public.product_variants(id) on delete cascade,title_en text not null,title_hi text not null default '',discount_price numeric(12,2) not null check(discount_price>=0),starts_at timestamptz not null,ends_at timestamptz not null,active boolean not null default true,check(ends_at>starts_at));
create table public.shop_settings(id integer primary key default 1 check(id=1),shop_name text not null default 'The Dry Fruit House',tagline_en text not null default '',tagline_hi text not null default '',about_en text not null default '',about_hi text not null default '',phone text not null default '',whatsapp text not null default '',address text not null default '',hours text not null default '',instagram text not null default '',facebook text not null default '',maps_url text not null default '',logo_url text not null default '',hero_url text not null default '',announcement_en text not null default '',announcement_hi text not null default '');
insert into public.shop_settings(id,shop_name,tagline_en,tagline_hi,about_en,about_hi) values(1,'The Dry Fruit House','Naturally good. Beautifully fresh.','प्राकृतिक स्वाद, बेहतरीन गुणवत्ता','Explore our handpicked selection of dry fruits. Contact us for details.','हमारे चुनिंदा ड्राई फ्रूट्स देखें। अधिक जानकारी के लिए संपर्क करें।') on conflict(id) do nothing;
create index on public.products(category_id);create index on public.product_variants(product_id);create index on public.product_images(product_id);create index on public.promotions(product_id);
create function public.is_shop_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admin_profiles where user_id=(select auth.uid())); $$;
revoke all on function public.is_shop_admin() from public;
grant execute on function public.is_shop_admin() to authenticated,anon;
create function public.touch_product() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
create trigger touch_products before update on public.products for each row execute function public.touch_product();
-- Keep a promotion's variant tied to the same product.
create function public.validate_promotion_variant() returns trigger language plpgsql set search_path='' as $$begin if new.variant_id is not null and not exists(select 1 from public.product_variants where id=new.variant_id and product_id=new.product_id) then raise exception 'Variant belongs to a different product';end if;return new;end$$;
create trigger validate_promotion before insert or update on public.promotions for each row execute function public.validate_promotion_variant();
alter table public.admin_profiles enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.product_variants enable row level security;
alter table public.product_images enable row level security;
alter table public.promotions enable row level security;
alter table public.shop_settings enable row level security;
create policy admin_read_self on public.admin_profiles for select to authenticated using(user_id=(select auth.uid()));
create policy category_public_read on public.categories for select to anon,authenticated using(true);
create policy product_public_read on public.products for select to anon,authenticated using(active or (select public.is_shop_admin()));
create policy variant_public_read on public.product_variants for select to anon,authenticated using((active and exists(select 1 from public.products p where p.id=product_id and p.active)) or (select public.is_shop_admin()));
create policy image_public_read on public.product_images for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and p.active) or (select public.is_shop_admin()));
create policy promo_public_read on public.promotions for select to anon,authenticated using((active and exists(select 1 from public.products p where p.id=product_id and p.active)) or (select public.is_shop_admin()));
create policy settings_public_read on public.shop_settings for select to anon,authenticated using(true);
create policy category_admin_all on public.categories for all to authenticated using((select public.is_shop_admin())) with check((select public.is_shop_admin()));
create policy product_admin_all on public.products for all to authenticated using((select public.is_shop_admin())) with check((select public.is_shop_admin()));
create policy variant_admin_all on public.product_variants for all to authenticated using((select public.is_shop_admin())) with check((select public.is_shop_admin()));
create policy image_admin_all on public.product_images for all to authenticated using((select public.is_shop_admin())) with check((select public.is_shop_admin()));
create policy promo_admin_all on public.promotions for all to authenticated using((select public.is_shop_admin())) with check((select public.is_shop_admin()));
create policy settings_admin_all on public.shop_settings for all to authenticated using((select public.is_shop_admin())) with check((select public.is_shop_admin()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,3145728,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy shop_images_public_read on storage.objects for select to anon,authenticated using(bucket_id='product-images');
create policy shop_images_admin_insert on storage.objects for insert to authenticated with check(bucket_id='product-images' and (select public.is_shop_admin()));
create policy shop_images_admin_update on storage.objects for update to authenticated using(bucket_id='product-images' and (select public.is_shop_admin())) with check(bucket_id='product-images' and (select public.is_shop_admin()));
create policy shop_images_admin_delete on storage.objects for delete to authenticated using(bucket_id='product-images' and (select public.is_shop_admin()));
